import dns from "node:dns/promises";
import { isIP } from "node:net";
import { rootLogger } from "../shared/logger";

const logger = rootLogger.child("deploy-hook");

const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 250;
const REQUEST_TIMEOUT_MS = 5_000;

export interface DeployHookResult {
  readonly ok: boolean;
  readonly attempts: number;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// `deployHookUrl` is a plain text field a customer fills in themselves, so
// every call here is an outbound request to a URL this server did not
// choose. The checks below turn that into a request to a host confirmed
// public at request time, not just a URL that merely parses — see
// docs/deploy-hooks.md for the reasoning and the list of what's blocked.

const RESERVED_IPV4_CIDRS = [
  "0.0.0.0/8", // "this network"
  "10.0.0.0/8", // RFC 1918
  "100.64.0.0/10", // carrier-grade NAT
  "127.0.0.0/8", // loopback
  "169.254.0.0/16", // link-local, incl. cloud metadata (169.254.169.254)
  "172.16.0.0/12", // RFC 1918
  "192.0.0.0/24", // IETF protocol assignments
  "192.168.0.0/16", // RFC 1918
  "198.18.0.0/15", // benchmarking
  "224.0.0.0/4", // multicast
  "240.0.0.0/4", // reserved
];

const INTERNAL_HOSTNAME_SUFFIXES = [".internal", ".localhost"];
const INTERNAL_HOSTNAMES = new Set(["localhost", "metadata.google.internal"]);

function ipv4ToInt(ip: string): number {
  const octets = ip.split(".").map(Number);
  return octets.reduce((acc, octet) => (acc << 8) + octet, 0) >>> 0;
}

function isReservedIpv4(ip: string): boolean {
  const target = ipv4ToInt(ip);
  return RESERVED_IPV4_CIDRS.some((cidr) => {
    const [range, bitsStr] = cidr.split("/");
    const bits = Number(bitsStr);
    const mask = bits === 0 ? 0 : (~0 << (32 - bits)) >>> 0;
    return (target & mask) === (ipv4ToInt(range) & mask);
  });
}

function isReservedIpv6(ip: string): boolean {
  const normalized = ip.toLowerCase();

  // An IPv4-mapped or IPv4-compatible IPv6 address carries the real address
  // it represents in its final segment (e.g. "::ffff:169.254.169.254") —
  // check that embedded address rather than the wrapper.
  const mappedIpv4 = normalized.match(/(?:^|:)(\d+\.\d+\.\d+\.\d+)$/)?.[1];
  if (mappedIpv4) return isReservedIpv4(mappedIpv4);

  if (normalized === "::" || normalized === "::1") return true; // unspecified / loopback

  const firstHextet = normalized.startsWith("::")
    ? 0
    : parseInt(normalized.split(":")[0] || "0", 16);

  if (firstHextet >= 0xfe80 && firstHextet <= 0xfebf) return true; // link-local, fe80::/10
  if (firstHextet >= 0xfc00 && firstHextet <= 0xfdff) return true; // unique local, fc00::/7 (incl. Azure/AWS metadata)
  if (firstHextet >= 0xff00 && firstHextet <= 0xffff) return true; // multicast, ff00::/8

  return false;
}

function isReservedIp(ip: string): boolean {
  const family = isIP(ip);
  if (family === 4) return isReservedIpv4(ip);
  if (family === 6) return isReservedIpv6(ip);
  return true; // not a recognizable IP literal — fail closed
}

class UnsafeDeployHookUrlError extends Error {}

/**
 * Confirms `url` is an `http(s)` URL whose host resolves only to public,
 * routable addresses. Throws `UnsafeDeployHookUrlError` otherwise. Resolves
 * fresh on every call (each retry calls this again) rather than caching,
 * since the whole point is to catch a host whose DNS answer has changed
 * since the last look.
 */
async function assertSafeDeployHookUrl(url: string): Promise<URL> {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new UnsafeDeployHookUrlError(`"${url}" is not a valid URL.`);
  }

  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new UnsafeDeployHookUrlError(`"${parsed.protocol}" is not an allowed scheme.`);
  }

  const hostname = parsed.hostname.toLowerCase();
  if (
    INTERNAL_HOSTNAMES.has(hostname) ||
    INTERNAL_HOSTNAME_SUFFIXES.some((suffix) => hostname.endsWith(suffix))
  ) {
    throw new UnsafeDeployHookUrlError(`"${hostname}" is not an allowed host.`);
  }

  const literalIpFamily = isIP(hostname);
  const addresses =
    literalIpFamily !== 0
      ? [hostname]
      : await dns.lookup(hostname, { all: true, verbatim: true }).then((records) =>
          records.map((record) => record.address),
        );

  if (addresses.length === 0 || addresses.some(isReservedIp)) {
    throw new UnsafeDeployHookUrlError(`"${hostname}" does not resolve to a public address.`);
  }

  return parsed;
}

/**
 * Calls a site's deploy hook after a publish. Most static-hosting deploy
 * hooks are a bare POST with no body, and most are flaky enough on a cold
 * start to be worth one retry — this gives it two.
 *
 * A failed hook does not fail the publish: the post and its revision are
 * already committed by the time this runs (see routes in app.ts), so the
 * worst case is a site that doesn't rebuild on its own. The caller surfaces
 * `ok: false` to the editor rather than losing the failure silently.
 */
export async function triggerDeployHook(siteSlug: string, url: string): Promise<DeployHookResult> {
  let lastError: unknown;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      const safeUrl = await assertSafeDeployHookUrl(url);
      logger.debug({ siteSlug, attempt }, "Started calling the deploy hook.");
      const response = await fetch(safeUrl, {
        method: "POST",
        redirect: "manual", // a redirect could point anywhere; never follow one blind
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (response.type === "opaqueredirect" || (response.status >= 300 && response.status < 400)) {
        throw new UnsafeDeployHookUrlError("Deploy hook responded with a redirect.");
      }
      if (!response.ok) {
        throw new Error(`Deploy hook responded with status ${response.status}.`);
      }
      logger.info({ siteSlug, attempt }, "Completed calling the deploy hook.");
      return { ok: true, attempts: attempt };
    } catch (error) {
      lastError = error;
      const reason = error instanceof Error ? error.message : String(error);
      if (error instanceof UnsafeDeployHookUrlError) {
        logger.error({ siteSlug, attempt, reason }, "Deploy hook URL is not safe to call; giving up.");
        return { ok: false, attempts: attempt };
      }
      logger.warn({ siteSlug, attempt, reason }, "Deploy hook call failed; retrying.");
      if (attempt < MAX_ATTEMPTS) await sleep(RETRY_DELAY_MS * attempt);
    }
  }

  const reason = lastError instanceof Error ? lastError.message : String(lastError);
  logger.error(
    { siteSlug, attempts: MAX_ATTEMPTS, reason },
    "Deploy hook failed after every retry.",
  );
  return { ok: false, attempts: MAX_ATTEMPTS };
}

