import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { triggerDeployHook } from "./deploy-hook";

vi.mock("node:dns/promises", () => ({
  default: { lookup: vi.fn() },
}));

const dns = await import("node:dns/promises");

function mockPublicDns() {
  vi.mocked(dns.default.lookup).mockResolvedValue([
    { address: "203.0.113.10", family: 4 },
  ]);
}

describe("triggerDeployHook", () => {
  beforeEach(() => {
    vi.stubGlobal("fetch", vi.fn());
    mockPublicDns();
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("succeeds on the first attempt", async () => {
    vi.mocked(fetch).mockResolvedValue(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 1 });
    expect(fetch).toHaveBeenCalledTimes(1);
    expect(fetch).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({ redirect: "manual" }),
    );
  });

  it("retries once after a network failure and then succeeds", async () => {
    vi.mocked(fetch)
      .mockRejectedValueOnce(new Error("network down"))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 2 });
  });

  it("treats a non-2xx response as a failure worth retrying", async () => {
    vi.mocked(fetch)
      .mockResolvedValueOnce(new Response(null, { status: 503 }))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(true);
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it("gives up after exhausting every retry", async () => {
    vi.mocked(fetch).mockRejectedValue(new Error("network down"));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(false);
    expect(result.attempts).toBe(3);
    expect(fetch).toHaveBeenCalledTimes(3);
  });

  describe("SSRF protections", () => {
    it("rejects a non-http(s) scheme without ever calling fetch", async () => {
      const result = await triggerDeployHook("acme", "file:///etc/passwd");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a malformed URL without ever calling fetch", async () => {
      const result = await triggerDeployHook("acme", "not a url");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects known-internal hostnames without a DNS lookup", async () => {
      const result = await triggerDeployHook("acme", "http://metadata.google.internal/deploy");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
      expect(dns.default.lookup).not.toHaveBeenCalled();
    });

    it("rejects localhost without a DNS lookup", async () => {
      const result = await triggerDeployHook("acme", "http://localhost:4000/deploy");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a loopback IP literal", async () => {
      const result = await triggerDeployHook("acme", "http://127.0.0.1/deploy");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects the cloud metadata address as an IP literal", async () => {
      const result = await triggerDeployHook("acme", "http://169.254.169.254/latest/meta-data");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname that resolves to a private address", async () => {
      vi.mocked(dns.default.lookup).mockResolvedValue([{ address: "10.0.0.5", family: 4 }]);

      const result = await triggerDeployHook("acme", "https://internal.example.invalid/deploy");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname with mixed public and reserved resolved addresses", async () => {
      vi.mocked(dns.default.lookup).mockResolvedValue([
        { address: "203.0.113.10", family: 4 },
        { address: "169.254.169.254", family: 4 },
      ]);

      const result = await triggerDeployHook("acme", "https://rebinding.example.invalid/deploy");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a reserved IPv6 literal", async () => {
      const result = await triggerDeployHook("acme", "http://[fd00:ec2::254]/deploy");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("does not follow a redirect response", async () => {
      vi.mocked(fetch).mockResolvedValue(
        new Response(null, { status: 302, headers: { location: "http://169.254.169.254/" } }),
      );

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 1 });
      expect(fetch).toHaveBeenCalledTimes(1);
    });

    it("re-validates the URL on every retry", async () => {
      vi.mocked(fetch).mockRejectedValue(new Error("network down"));

      await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(dns.default.lookup).toHaveBeenCalledTimes(3);
    });
  });
});

